const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const region = ee.Geometry.Point(-70.0, -30.0).buffer(50000); // 50km buffer around a point in north-central Chile
  const scale = 1000; // Resolution for analysis in meters

  const date1_start = '2022-07-15';
  const date1_end = '2022-07-17'; // July 16, 2022
  const date2_start = '2022-07-06';
  const date2_end = '2022-07-08'; // July 7, 2022

  // Function to mask clouds from Sentinel-2 QA60 band
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Apply mask and scale surface reflectance
  }

  // Function to calculate NDSI and create a snow mask
  function addNDSI(image) {
    // NDSI = (Green - SWIR1) / (Green + SWIR1)
    // Sentinel-2 bands: B3 (Green), B11 (SWIR1)
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    const snow = ndsi.gt(0.4).and(image.select('B3').gt(0.1)).rename('snow'); // NDSI > 0.4 and Green > 0.1 for snow
    return image.addBands(ndsi).addBands(snow);
  }

  // 2. Data Acquisition & Check
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(region)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50)) // Filter for images with less than 50% cloud cover initially
    .map(maskS2clouds)
    .map(addNDSI);

  const col1 = s2Collection.filterDate(date1_start, date1_end);
  const col2 = s2Collection.filterDate(date2_start, date2_end);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`2022-07-16 Images: ${size1}`);
    console.log(`2022-07-07 Images: ${size2}`);
    console.log("No images found for one or both comparison points within the narrow date range and initial cloud filter.");
    console.log("C1");
    return;
  }

  // Get the best image for each period (e.g., least cloudy)
  const image1 = col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const image2 = col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  if (!image1 || !image2) {
    console.log("C1"); // Should not happen if size > 0 but good to double check
    return;
  }

  const cloudPerc1 = await image1.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();
  const cloudPerc2 = await image2.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();

  // 3. Processing and Calculation of snow area
  // Calculate area of each pixel in square meters
  const pixelArea = ee.Image.pixelArea().mask(image1.select('snow').mask());

  const snowMask1 = image1.select('snow').multiply(pixelArea); // Multiply by pixel area to get snow area per pixel
  const snowMask2 = image2.select('snow').multiply(pixelArea);

  const reducer = ee.Reducer.sum();

  const snowArea1Result = await snowMask1.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326', // Use WGS84 as CRS to avoid projection issues
  }).get('snow');

  const snowArea2Result = await snowMask2.reduceRegion({
    reducer: reducer,
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326',
  }).get('snow');

  const snowArea1 = snowArea1Result ? snowArea1Result.getInfo() : null;
  const snowArea2 = snowArea2Result ? snowArea2Result.getInfo() : null;

  // Check for C2: No Valid Pixels (after all masking, 0 pixels remain for calculation)
  // This is implicitly handled by snowArea being 0 if no pixels remain or if no snow.
  // We can explicitly check for valid pixels if needed, but for snow area, a 0 is a valid measurement.
  const validPixels1 = await image1.select('snow').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326',
  }).get('snow').getInfo();

  const validPixels2 = await image2.select('snow').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: scale,
    maxPixels: 1e9,
    crs: 'EPSG:4326',
  }).get('snow').getInfo();

  if (validPixels1 === 0 && validPixels2 === 0) {
    console.log(`Valid pixels 2022-07-16: ${validPixels1}`);
    console.log(`Valid pixels 2022-07-07: ${validPixels2}`);
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  if (snowArea1 === null || isNaN(snowArea1) || snowArea2 === null || isNaN(snowArea2)) {
    console.log(`Snow Area 2022-07-16: ${snowArea1}`);
    console.log(`Snow Area 2022-07-07: ${snowArea2}`);
    console.log("C3");
    return;
  }

  const snowAreaKm2_1 = snowArea1 / 1e6; // Convert square meters to square kilometers
  const snowAreaKm2_2 = snowArea2 / 1e6;

  console.log(`2022-07-16 Images: ${size1}, Best Image Cloud %: ${cloudPerc1.toFixed(1)}`);
  console.log(`2022-07-07 Images: ${size2}, Best Image Cloud %: ${cloudPerc2.toFixed(1)}`);
  console.log(`Snow Area (sq km) on 2022-07-16: ${snowAreaKm2_1.toFixed(2)}`);
  console.log(`Snow Area (sq km) on 2022-07-07: ${snowAreaKm2_2.toFixed(2)}`);
  console.log(`Valid Pixels (2022-07-16): ${validPixels1}`);
  console.log(`Valid Pixels (2022-07-07): ${validPixels2}`);

  if (snowAreaKm2_1 > snowAreaKm2_2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
